import { useState } from 'react';
import {
  JxStepper,
  JxInputField,
  JxTextareaField,
  JxButton,
} from '@jinx-ui/react';

interface RegistrationFormProps {
  onSubmit: (data: {
    fullName: string;
    email: string;
    phone: string;
    address: string;
    city: string;
    postalCode: string;
  }) => void;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);

  const [fullName, setFullName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');

  const [address, setAddress] = useState('');
  const [city, setCity] = useState('');
  const [postalCode, setPostalCode] = useState('');

  const emailError =
    email.length > 0 && !email.includes('@') ? 'Укажите адрес с символом @' : undefined;

  const canGoNextFromContacts = fullName.trim().length > 0 && email.trim().length > 0 && !emailError;
  const canGoNextFromAddress = address.trim().length > 0 && city.trim().length > 0;

  const isNextDisabled =
    (step === 0 && !canGoNextFromContacts) || (step === 1 && !canGoNextFromAddress);

  const goBack = () => setStep((current) => Math.max(current - 1, 0));
  const goNext = () => setStep((current) => Math.min(current + 1, steps.length - 1));

  const handleSubmit = () => {
    onSubmit({ fullName, email, phone, address, city, postalCode });
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '24px',
        maxWidth: '480px',
      }}
    >
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
          <JxInputField
            label="Имя и фамилия"
            required
            value={fullName}
            onChange={(event) => setFullName(event.target.value)}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={email}
            onChange={(event) => setEmail(event.target.value)}
            errorText={emailError}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            value={phone}
            onChange={(event) => setPhone(event.target.value)}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
          <JxTextareaField
            label="Адрес"
            required
            rows={3}
            value={address}
            onChange={(event) => setAddress(event.target.value)}
          />
          <JxInputField
            label="Город"
            required
            value={city}
            onChange={(event) => setCity(event.target.value)}
          />
          <JxInputField
            label="Почтовый индекс"
            value={postalCode}
            onChange={(event) => setPostalCode(event.target.value)}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
          <p style={{ margin: 0, color: 'var(--jx-text-2)' }}>Проверьте данные перед отправкой</p>
          <div
            style={{
              display: 'flex',
              flexDirection: 'column',
              gap: '4px',
              padding: '16px',
              borderRadius: 'var(--jx-r-lg)',
              border: '1px solid var(--jx-border)',
              background: 'var(--jx-surface-2)',
              color: 'var(--jx-text)',
            }}
          >
            <span>
              <strong>Имя:</strong> {fullName || '—'}
            </span>
            <span>
              <strong>Почта:</strong> {email || '—'}
            </span>
            <span>
              <strong>Телефон:</strong> {phone || '—'}
            </span>
            <span>
              <strong>Адрес:</strong> {address || '—'}
            </span>
            <span>
              <strong>Город:</strong> {city || '—'}
            </span>
            <span>
              <strong>Индекс:</strong> {postalCode || '—'}
            </span>
          </div>
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: '12px' }}>
        <JxButton variant="ghost" onClick={goBack} disabled={step === 0}>
          Назад
        </JxButton>
        {step < steps.length - 1 ? (
          <JxButton variant="primary" onClick={goNext} disabled={isNextDisabled}>
            Дальше
          </JxButton>
        ) : (
          <JxButton variant="primary" onClick={handleSubmit}>
            Отправить
          </JxButton>
        )}
      </div>
    </div>
  );
}

